\begin{corollary}[6.5.9]
\label{III.6.5.9}
Sean $X$ e $Y$ dos $S$-preesquemas, y sea $\mathscr P_\bullet$
\textup{(respectivamente} $\mathscr Q_\bullet$\textup{)} un complejo
\oldpage[III]{151}
acotado
