  \boldsymbol{\mathscr{T}\!or}_n^S
  (f_1,f_2;\mathscr P_\bullet^{(1)},\mathscr P_\bullet^{(2)})
  \xrightarrow{\sim}
  \bigoplus_{q_1+q_2=n}
  \mathcal H^{-q_1}(f_1,\mathscr P_\bullet^{(1)})
  \otimes_S
  \mathcal H^{-q_2}(f_2,\mathscr P_\bullet^{(2)}).
  \tag{6.7.7.1}\label{III.6.7.7.1.fr}
\]
\end{env}
\end{proposition}

