before:
\begin{corollary}[6.9.6]
\label{III.6.9.6}
Bajo las condiciones de \sref{III.6.9.1}, supongamos que:
\begin{enumerate}
  \item[$1^\circ$] Los complejos $\mathscr P_\bullet^{(i)}$ están formados
  por módulos planos sobre $S$, y los $\mathscr O_Y$-módulos
  \[
    \mathfrak{Tor}_n^S
    (f_1,\ldots,f_m;
     \mathscr P_\bullet^{(1)},\ldots,\mathscr P_\bullet^{(m)})
  \]
  son planos sobre $S$.
  \item[$2^\circ$] Los $\mathscr P_\bullet^{(i)}$ y
  $\mathscr Q'_\bullet$ están acotados inferiormente.
\end{enumerate}

\oldpage[III]{169}
Se tienen entonces, poniendo
$\mathscr P_\bullet'^{(i)}=
\mathscr P_\bullet^{(i)}\otimes_{\mathscr O_S}\mathscr O_{S'}$,
isomorfismos canónicos funtoriales
\begin{env}[6.9.6.1]
\label{III.6.9.6.1}
\[
\begin{split}
  &\mathfrak{Tor}_n^{S'}
  (f'_1,\ldots,f'_m,1_{S'};
   \mathscr P_\bullet'^{(1)},\ldots,
   \mathscr P_\bullet'^{(m)},\mathscr Q'_\bullet)
  \xrightarrow{\sim}\\
  &\qquad\xrightarrow{\sim}
  \bigoplus_{n'+n''=n}
  \mathfrak{Tor}_{n'}^S
  (f_1,\ldots,f_m;
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)})
  \otimes_S\mathscr H_{n''}(\mathscr Q'_\bullet).
\end{split}
\tag{6.9.6.1}\label{III.6.9.6.1.fr}
\]
\end{env}
En particular, para $\mathscr Q'_\bullet$ reducido a un solo término
$\mathscr F'$ de grado $0$, se tienen isomorfismos canónicos funtoriales
\begin{env}[6.9.6.2]
\label{III.6.9.6.2}
\[
\begin{split}
  &\mathfrak{Tor}_n^{S'}
  (f'_1,\ldots,f'_m,1_{S'};
   \mathscr P_\bullet'^{(1)},\ldots,
   \mathscr P_\bullet'^{(m)},\mathscr F')
  \xrightarrow{\sim}\\
  &\qquad
  \mathfrak{Tor}_n^S
  (f_1,\ldots,f_m;
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)})
  \otimes_{\mathscr O_S}\mathscr F'
\end{split}
\tag{6.9.6.2}\label{III.6.9.6.2.fr}
\]
\end{env}
y, más particularmente, para $\mathscr F'=\mathscr O_{S'}$,
\begin{env}[6.9.6.3]
\label{III.6.9.6.3}
\[
\begin{split}
  &\mathfrak{Tor}_n^{S'}
  (f'_1,\ldots,f'_m;
   \mathscr P_\bullet'^{(1)},\ldots,
   \mathscr P_\bullet'^{(m)})
  \xrightarrow{\sim}\\
  &\qquad
  \mathfrak{Tor}_n^S
  (f_1,\ldots,f_m;
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)})
  \otimes_{\mathscr O_S}\mathscr O_{S'}.
\end{split}
\tag{6.9.6.3}\label{III.6.9.6.3.fr}
\]
\end{env}
\end{corollary}

\begin{proof}
La hipótesis de planitud sobre los módulos que componen los
$\mathscr P_\bullet^{(i)}$ implica que los complejos
$\mathscr{T}\!or_{q_i}^S(\mathscr P_\bullet^{(i)},\mathscr O_{S'})$ son nulos
para $q_i\ne0$ por \sref{III.6.5.8}. La sucesión $(f')$ es, por tanto,
degenerada; la hipótesis $2^\circ$ implica además que es birregular
\sref{III.6.9.3}, de modo que el homomorfismo de borde
\[
\begin{split}
  &\mathfrak{Tor}_n^S
  (f_1,\ldots,f_m,1_{S'};
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)},\mathscr Q'_\bullet)
  \longrightarrow {}^{(f')}\mathscr E_{n0}^2=\\
  &\qquad=
  \mathfrak{Tor}_n^{S'}
  (f'_1,\ldots,f'_m,1_{S'};
   \mathscr P_\bullet'^{(1)},\ldots,
   \mathscr P_\bullet'^{(m)},\mathscr Q'_\bullet)
\end{split}
\tag{6.9.6.4}\label{III.6.9.6.4.fr}
\]
es biyectivo por \sref[0]{0.11.1.6}. La hipótesis de planitud sobre los
módulos
\[
  \mathfrak{Tor}_n^S
  (f_1,\ldots,f_m;
   \mathscr P_\bullet^{(1)},\ldots,\mathscr P_\bullet^{(m)})
\]
implica que ${}^{(e)}\mathscr E_{pq}^2=0$ para $p\ne0$ por
\sref{III.6.5.8}. La sucesión $(e)$ es, por tanto, también degenerada y, como
es birregular, el homomorfismo de borde
\[
\begin{split}
  &\mathfrak{Tor}_n^S
  (f_1,\ldots,f_m,1_{S'};
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)},\mathscr Q'_\bullet)
  \longrightarrow {}^{(e)}\mathscr E_{0n}^2=\\
  &\qquad=
  \bigoplus_{n'+n''=n}
  \mathfrak{Tor}_{n'}^S
  (f_1,\ldots,f_m;
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)})
  \otimes_{\mathscr O_S}\mathscr H_{n''}(\mathscr Q'_\bullet)
\end{split}
\tag{6.9.6.5}\label{III.6.9.6.5.fr}
\]
es biyectivo; combinando los dos isomorfismos precedentes se obtiene el
isomorfismo \sref{III.6.9.6.1}. El isomorfismo \sref{III.6.9.6.2} se deduce
de este trivialmente, puesto que entonces se tiene
$\mathscr H_q(\mathscr Q'_\bullet)=0$ si $q\ne0$ y
$\mathscr H_0(\mathscr Q'_\bullet)=\mathscr F'$. Finalmente, el caso
$\mathscr F'=\mathscr O_{S'}$ en \sref{III.6.9.6.2}, teniendo en cuenta
\sref{III.6.7.12}, da el isomorfismo \sref{III.6.9.6.3}.
\end{proof}

after:
\begin{corollary}[6.9.6]
\label{III.6.9.6}
Bajo las condiciones de \sref{III.6.9.1}, supongamos que:
\begin{enumerate}
  \item[$1^\circ$] Los complejos $\mathscr P_\bullet^{(i)}$ están formados
  por módulos planos sobre $S$, y los $\mathscr O_Y$-módulos
  \[
    \mathfrak{Tor}_n^S
    (f_1,\ldots,f_m;
     \mathscr P_\bullet^{(1)},\ldots,\mathscr P_\bullet^{(m)})
  \]
  son planos sobre $S$.
  \item[$2^\circ$] Los $\mathscr P_\bullet^{(i)}$ y
  $\mathscr Q'_\bullet$ están acotados inferiormente.
\end{enumerate}

\oldpage[III]{169}
Se tienen entonces, poniendo
$\mathscr P_\bullet'^{(i)}=
\mathscr P_\bullet^{(i)}\otimes_{\mathscr O_S}\mathscr O_{S'}$,
isomorfismos canónicos funtoriales

\label{III.6.9.6.1}
\[
\begin{split}
  &\mathfrak{Tor}_n^{S'}
  (f'_1,\ldots,f'_m,1_{S'};
   \mathscr P_\bullet'^{(1)},\ldots,
   \mathscr P_\bullet'^{(m)},\mathscr Q'_\bullet)
  \xrightarrow{\sim}\\
  &\qquad\xrightarrow{\sim}
  \bigoplus_{n'+n''=n}
  \mathfrak{Tor}_{n'}^S
  (f_1,\ldots,f_m;
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)})
  \otimes_S\mathscr H_{n''}(\mathscr Q'_\bullet).
\end{split}
\tag{6.9.6.1}\label{III.6.9.6.1.fr}
\]

En particular, para $\mathscr Q'_\bullet$ reducido a un solo término
$\mathscr F'$ de grado $0$, se tienen isomorfismos canónicos funtoriales

\label{III.6.9.6.2}
\[
\begin{split}
  &\mathfrak{Tor}_n^{S'}
  (f'_1,\ldots,f'_m,1_{S'};
   \mathscr P_\bullet'^{(1)},\ldots,
   \mathscr P_\bullet'^{(m)},\mathscr F')
  \xrightarrow{\sim}\\
  &\qquad
  \mathfrak{Tor}_n^S
  (f_1,\ldots,f_m;
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)})
  \otimes_{\mathscr O_S}\mathscr F'
\end{split}
\tag{6.9.6.2}\label{III.6.9.6.2.fr}
\]

y, más particularmente, para $\mathscr F'=\mathscr O_{S'}$,

\label{III.6.9.6.3}
\[
\begin{split}
  &\mathfrak{Tor}_n^{S'}
  (f'_1,\ldots,f'_m;
   \mathscr P_\bullet'^{(1)},\ldots,
   \mathscr P_\bullet'^{(m)})
  \xrightarrow{\sim}\\
  &\qquad
  \mathfrak{Tor}_n^S
  (f_1,\ldots,f_m;
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)})
  \otimes_{\mathscr O_S}\mathscr O_{S'}.
\end{split}
\tag{6.9.6.3}\label{III.6.9.6.3.fr}
\]

\end{corollary}

\begin{proof}
La hipótesis de planitud sobre los módulos que componen los
$\mathscr P_\bullet^{(i)}$ implica que los complejos
$\mathscr{T}\!or_{q_i}^S(\mathscr P_\bullet^{(i)},\mathscr O_{S'})$ son nulos
para $q_i\ne0$ por \sref{III.6.5.8}. La sucesión $(f')$ es, por tanto,
degenerada; la hipótesis $2^\circ$ implica además que es birregular
\sref{III.6.9.3}, de modo que el homomorfismo de borde
\[
\begin{split}
  &\mathfrak{Tor}_n^S
  (f_1,\ldots,f_m,1_{S'};
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)},\mathscr Q'_\bullet)
  \longrightarrow {}^{(f')}\mathscr E_{n0}^2=\\
  &\qquad=
  \mathfrak{Tor}_n^{S'}
  (f'_1,\ldots,f'_m,1_{S'};
   \mathscr P_\bullet'^{(1)},\ldots,
   \mathscr P_\bullet'^{(m)},\mathscr Q'_\bullet)
\end{split}
\tag{6.9.6.4}\label{III.6.9.6.4.fr}
\]
es biyectivo por \sref[0]{0.11.1.6}. La hipótesis de planitud sobre los
módulos
\[
  \mathfrak{Tor}_n^S
  (f_1,\ldots,f_m;
   \mathscr P_\bullet^{(1)},\ldots,\mathscr P_\bullet^{(m)})
\]
implica que ${}^{(e)}\mathscr E_{pq}^2=0$ para $p\ne0$ por
\sref{III.6.5.8}. La sucesión $(e)$ es, por tanto, también degenerada y, como
es birregular, el homomorfismo de borde
\[
\begin{split}
  &\mathfrak{Tor}_n^S
  (f_1,\ldots,f_m,1_{S'};
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)},\mathscr Q'_\bullet)
  \longrightarrow {}^{(e)}\mathscr E_{0n}^2=\\
  &\qquad=
  \bigoplus_{n'+n''=n}
  \mathfrak{Tor}_{n'}^S
  (f_1,\ldots,f_m;
   \mathscr P_\bullet^{(1)},\ldots,
   \mathscr P_\bullet^{(m)})
  \otimes_{\mathscr O_S}\mathscr H_{n''}(\mathscr Q'_\bullet)
\end{split}
\tag{6.9.6.5}\label{III.6.9.6.5.fr}
\]
es biyectivo; combinando los dos isomorfismos precedentes se obtiene el
isomorfismo \sref{III.6.9.6.1}. El isomorfismo \sref{III.6.9.6.2} se deduce
de este trivialmente, puesto que entonces se tiene
$\mathscr H_q(\mathscr Q'_\bullet)=0$ si $q\ne0$ y
$\mathscr H_0(\mathscr Q'_\bullet)=\mathscr F'$. Finalmente, el caso
$\mathscr F'=\mathscr O_{S'}$ en \sref{III.6.9.6.2}, teniendo en cuenta
\sref{III.6.7.12}, da el isomorfismo \sref{III.6.9.6.3}.
\end{proof}

before:
\begin{corollary}[2.3.7]
\label{III.2.3.7}
Sean $X$ e $Y$ esquemas integrales proyectivos sobre un cuerpo $k$, y sea
$f:X\to Y$
un $k$-morfismo birracional.
Entonces $X$ es $k$-isomorfo a un $Y$-esquema obtenido por explosión de un subesquema cerrado $Y'$ de $Y$, no necesariamente reducido.
\end{corollary}

\begin{proof}
\oldpage[III]{107}
En efecto, $f$ es proyectivo \sref[II]{II.5.5.5}[v], y como $Y$ es proyectivo sobre $k$, se satisface la condición adicional de \sref{III.2.3.6}.
Basta, por tanto, tomar el subesquema cerrado $Y'$ de $Y$ definido por el ideal coherente $\mathcal J$ de \sref{III.2.3.6}.
\end{proof}

