Sea $(X,\mathcal O_X)$ un espacio anillado.
Recordemos que, para todo $\mathcal O_X$-módulo $\mathcal F$, se define la
\emph{cohomología} $H^\bullet(X,\mathcal F)$, que es un \emph{funtor cohomológico universal}
(T, 2.2) de la categoría $\boldsymbol{C}(X)$ de
$\mathcal O_X$-módulos en la categoría de grupos abelianos; es el funtor derivado
del funtor exacto por la izquierda
$\mathcal F\to\Gamma(X,\mathcal F)$.
El funtor $H^\bullet(X,\mathcal F)$ es isomorfo
\oldpage[0\textsubscript{III}]{50}
a la restricción a la categoría $\boldsymbol{C}(X)$ del funtor cohomológico
definido del mismo modo sobre la categoría de haces de grupos abelianos
en $X$ (G, II, 7.2.1).
\end{env}

\begin{env}[1.1.2]
\label{III.1.1.2}
Para todo $A$-módulo $M$, se define el \emph{complejo de cadenas}
\begin{equation}
\label{III.1.1.2.1-fr}
\tag{1.1.2.1}
K_\bullet(\mathbf f,M)=K_\bullet(\mathbf f)\otimes_A M
\end{equation}
y el \emph{complejo de cocadenas} (G, I, 2.2)
\begin{equation}
\label{III.1.1.2.2-fr}
\tag{1.1.2.2}
K^\bullet(\mathbf f,M)=\operatorname{Hom}_A(K_\bullet(\mathbf f),M).
\end{equation}

Si $g$ es una $k$-cocadena de este último complejo y se pone
\[
g(i_1,\ldots,i_k)=g(\mathbf e_{i_1}\wedge\ldots\wedge\mathbf e_{i_k}),
\]
entonces $g$ se identifica con una aplicación \emph{alternada} de $[1,r]^k$ en $M$, y de las definiciones anteriores se deduce que
\begin{equation}
\label{III.1.1.2.3-fr}
\tag{1.1.2.3}
d^kg(i_1,i_2,\ldots,i_{k+1})=
\sum_{h=1}^{k+1}(-1)^{h-1}f_{i_h}
g(i_1,\ldots,\widehat{i}_h,\ldots,i_{k+1}).
\end{equation}
\end{env}

